-- 0091: Kurumsal sayfa içerikleri (KVKK, gizlilik, çerez, telif, editoryal ilkeler…).
--
-- Sayfalar Habertürk'teki kurumsal/yasal sayfa düzenine benzer biçimde
-- başlık + alt başlık + madde listeleriyle hazırlanmıştır. İçerikler TipTap
-- belgesi olarak saklanır; renderTipTapHTML başlık, liste ve alıntıyı destekler.
-- Var olan kayıtlar güncellenir (kilitli sayfalar silinmez).

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Kişisel Verilerin Korunması ve KVKK Aydınlatma Metni', 'kvkk', '6698 sayılı Kişisel Verilerin Korunması Kanunu kapsamında kişisel verilerinizin işlenmesine ilişkin aydınlatma metni.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu aydınlatma metni, 6698 sayılı Kişisel Verilerin Korunması Kanunu''nun (\"KVKK\") 10. maddesi ve Aydınlatma Yükümlülüğünün Yerine Getirilmesinde Uyulacak Usul ve Esaslar Hakkında Tebliğ uyarınca, theblock.com.tr internet sitesini ziyaret eden ve hizmetlerinden yararlanan kişileri bilgilendirmek amacıyla hazırlanmıştır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Veri Sorumlusu"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verileriniz; veri sorumlusu sıfatıyla theblock.com.tr tarafından aşağıda açıklanan kapsamda işlenmektedir. Veri sorumlusuna ilişkin iletişim bilgileri: e-posta info@theblock.com.tr, internet adresi theblock.com.tr."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. İşlenen Kişisel Veriler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitemizi ziyaret etmeniz ve hizmetlerimizi kullanmanız sırasında, hizmetin niteliğine göre aşağıdaki veri kategorileri işlenebilir:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kimlik verileri: ad, soyad (üyelik, yorum ve başvuru formlarında verdiğiniz ölçüde)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İletişim verileri: e-posta adresi, telefon numarası (yalnızca sizin ilettiğiniz durumlarda)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İşlem güvenliği verileri: IP adresi, tarayıcı ve cihaz bilgisi, oturum kayıtları, erişim zamanı."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kullanım verileri: ziyaret edilen sayfalar, tıklamalar, okuma süresi, tercih edilen dil ve tema."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pazarlama verileri: bülten aboneliği ve iletişim izinleriniz."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kullanıcı içeriği: yorumlar, geri bildirimler ve bize ilettiğiniz mesajlar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerez verileri: çerez politikamızda açıklanan teknik ve analitik veriler."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Kişisel Verilerin İşlenme Amaçları"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sitenin güvenli biçimde sunulması, hizmet sürekliliğinin sağlanması ve teknik hataların giderilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İçeriklerin ilgi alanlarınıza göre sunulması, okuma deneyiminin iyileştirilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Üyelik, yorum, kaydetme ve abonelik gibi işlevlerin yürütülmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Okuyucu istatistiklerinin ölçümlenmesi ve editoryal kararların desteklenmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam ve sponsorlu içeriklerin gösterilmesi, reklam performansının ölçülmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bülten ve bilgilendirme gönderimlerinin yönetilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hukuki yükümlülüklerin yerine getirilmesi ve yetkili kurumlara bilgi verilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Talep ve şikâyetlerin değerlendirilmesi, ilgili kişi başvurularının yanıtlanması."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Hukuki Sebepler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verileriniz; KVKK''nın 5. maddesinin ikinci fıkrasında sayılan açık rıza, kanunlarda açıkça öngörülme, sözleşmenin kurulması veya ifası, hukuki yükümlülüğün yerine getirilmesi, bir hakkın tesisi/kullanılması/korunması ve meşru menfaat hukuki sebeplerine dayanılarak işlenir. Pazarlama amaçlı elektronik ileti gönderimi için ayrıca 6563 sayılı Elektronik Ticaretin Düzenlenmesi Hakkında Kanun kapsamında onayınız alınır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Kişisel Verilerin Aktarılması"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verileriniz; hizmet aldığımız barındırma, e-posta gönderim, ölçümleme ve reklam altyapısı sağlayıcılarına, yalnızca ilgili hizmetin gerektirdiği ölçüde ve sözleşmesel güvenlik tedbirleri altında aktarılabilir. Yurt dışında sunucu bulunan hizmetlerde aktarım, KVKK''nın 9. maddesindeki şartlara uygun olarak yapılır. Yetkili kamu kurum ve kuruluşlarına aktarım yalnızca hukuki talep hâlinde gerçekleştirilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Saklama ve İmha"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel veriler, işleme amacının gerektirdiği süre ve ilgili mevzuatta öngörülen süreler boyunca saklanır. Süre sonunda veriler silinir, yok edilir veya anonim hâle getirilir. Erişim kayıtları, 5651 sayılı Kanun kapsamındaki yükümlülükler doğrultusunda belirlenen sürelerle tutulur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. İlgili Kişi Olarak Haklarınız"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "KVKK''nın 11. maddesi uyarınca aşağıdaki haklara sahipsiniz:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verilerinizin işlenip işlenmediğini öğrenme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İşlenmişse buna ilişkin bilgi talep etme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İşlenme amacını ve amaca uygun kullanılıp kullanılmadığını öğrenme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri bilme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Eksik veya yanlış işlenmiş verilerin düzeltilmesini isteme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Silinmesini veya yok edilmesini isteme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aktarım yapılan üçüncü kişilere düzeltme/silme işlemlerinin bildirilmesini isteme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Münhasıran otomatik sistemlerle yapılan analiz sonucu aleyhinize çıkan sonuca itiraz etme."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kanuna aykırı işleme nedeniyle zarara uğramanız hâlinde zararın giderilmesini talep etme."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Başvuru Yöntemi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haklarınıza ilişkin taleplerinizi info@theblock.com.tr adresine, KVKK''nın 13. maddesine uygun yazılı başvuru ile veya İlgili Kişi Başvuru Formu''nu doldurarak iletebilirsiniz. Başvurular en geç 30 gün içinde yanıtlanır. Başvurunuzda kimliğinizi tespit edici bilgiler ile talebinizin kapsamını açıkça belirtmeniz gerekir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Çerezler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitemizde zorunlu, işlevsel, ölçümleme ve reklam amaçlı çerezler kullanılmaktadır. Ayrıntılar için Çerez Politikası sayfamızı inceleyebilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "10. Güncellemeler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu metin; mevzuat değişiklikleri veya hizmetlerimizdeki değişiklikler doğrultusunda güncellenebilir. Güncel sürüm her zaman bu sayfada yayımlanır."}]}]}'::jsonb, 'yayinda', false, true, true)
ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    spot = EXCLUDED.spot,
    detail = EXCLUDED.detail,
    kind = EXCLUDED.kind,
    status = 'yayinda',
    in_footer = true,
    updated_at = now();

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'İlgili Kişi Başvuru Formu ve Aydınlatma Metni', 'kvkk-basvuru', 'KVKK kapsamındaki haklarınızı kullanmak için başvuru yöntemi ve form içeriği.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "6698 sayılı Kişisel Verilerin Korunması Kanunu''nun 11. ve 13. maddeleri uyarınca, kişisel verilerinize ilişkin taleplerinizi aşağıdaki yöntemlerle iletebilirsiniz. Başvurularınızın doğru ve hızlı değerlendirilmesi için formda istenen bilgileri eksiksiz doldurmanız önerilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Başvuruda Bulunabilecek Kişiler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yalnızca kendi kişisel verileri hakkında başvuru yapılabilir. Başkası adına başvuru yapılması hâlinde noter onaylı vekâletname veya yasal temsil belgesi eklenmelidir. Velayet altındaki çocuklar için yasal temsilci başvurabilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Başvuru Kanalları"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "E-posta: info@theblock.com.tr (konu satırına \"KVKK Başvurusu\" yazılması önerilir)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yazılı başvuru: site yönetiminin kayıtlı iletişim adresine ıslak imzalı dilekçe."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kayıtlı elektronik posta (KEP) üzerinden yapılan başvurular da kabul edilir."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Formda Yer Alması Gereken Bilgiler"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ad, soyad ve başvuru sahibinin imzası (e-posta başvurusunda ad soyad yeterlidir)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "T.C. kimlik numarası veya yabancılar için pasaport numarası."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tebligata esas yerleşim yeri adresi veya e-posta adresi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Başvuru konusuna ilişkin talep ve açıklamalar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Talebe ilişkin belge ve bilgiler (varsa)."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Talep Konuları"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Formda aşağıdaki taleplerden bir veya birkaçını işaretleyebilirsiniz:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verilerimin işlenip işlenmediğinin öğrenilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İşlenen veriler hakkında bilgi verilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İşleme amacının ve amaca uygunluğunun öğrenilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Aktarıldığı üçüncü kişilerin öğrenilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Eksik/yanlış verilerin düzeltilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Verilerin silinmesi veya yok edilmesi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Otomatik analiz sonucuna itiraz."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Zararın giderilmesi talebi."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Değerlendirme Süresi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Başvurunuz, niteliğine göre en geç 30 gün içinde ücretsiz olarak yanıtlanır. İşlemin ayrıca bir maliyet gerektirmesi hâlinde, Kişisel Verileri Koruma Kurulu tarafından belirlenen tarifedeki ücret talep edilebilir. Talebin reddedilmesi hâlinde gerekçe ve başvuru yolu bildirilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Veri Güvenliği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Başvuru sırasında ilettiğiniz belgeler yalnızca talebin değerlendirilmesi amacıyla işlenir ve mevzuatta öngörülen süre sonunda silinir. Başvuru sürecinde kimlik doğrulaması yapılabilir; bu amaçla istenen ek bilgiler yalnızca doğrulama için kullanılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Aydınlatma"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verilerinizin işlenmesine ilişkin ayrıntılı bilgi için Kişisel Verilerin Korunması ve KVKK Aydınlatma Metni sayfamızı inceleyebilirsiniz."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu form bir başvuru rehberidir; başvurunuzu e-posta ile ilettiğinizde formu ayrıca doldurmanız zorunlu değildir. Yine de talep kapsamını netleştirmek için formdaki başlıkları kullanmanız süreci hızlandırır."}]}]}]}'::jsonb, 'yayinda', false, true, true)
ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    spot = EXCLUDED.spot,
    detail = EXCLUDED.detail,
    kind = EXCLUDED.kind,
