    in_footer = true,
    updated_at = now();

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Gizlilik Politikası', 'gizlilik-politikasi', 'theblock.com.tr''nin kişisel verileri hangi ilkelerle topladığı, kullandığı ve koruduğu.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu gizlilik politikası, theblock.com.tr üzerinden sunulan hizmetlerde kişisel verilerin nasıl toplandığını, kullanıldığını, saklandığını ve korunduğunu açıklar. Politikamız, KVKK başta olmak üzere ilgili mevzuata uygun hareket etme ilkesine dayanır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Kapsam"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Politika; siteyi ziyaret eden tüm kullanıcıları, üyelik oluşturan okuyucuları, bülten abonelerini, yorum yapanları ve bizimle iletişime geçen kişileri kapsar. Üçüncü taraf sitelere verilen bağlantılar bu politikanın kapsamı dışındadır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Toplanan Bilgiler"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sizin doğrudan ilettiğiniz bilgiler: ad, e-posta, yorum içeriği, başvuru ve geri bildirim metinleri."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Otomatik toplanan teknik bilgiler: IP adresi, tarayıcı türü, işletim sistemi, ekran çözünürlüğü, dil, yönlendiren sayfa."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kullanım bilgileri: ziyaret edilen sayfalar, oturum süresi, tıklama ve kaydırma hareketleri."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerezler ve benzeri teknolojilerle elde edilen tercih bilgileri (tema, dil, yazı boyutu)."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Bilgilerin Kullanımı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Toplanan bilgiler; sitenin çalışmasını sağlamak, içerikleri sunmak, okuyucu deneyimini iyileştirmek, güvenliği korumak, yasal yükümlülükleri yerine getirmek ve izin verdiğiniz hâllerde bilgilendirme yapmak amacıyla kullanılır. Verileriniz hiçbir koşulda üçüncü kişilere satılmaz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Paylaşım"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bilgiler; barındırma, e-posta gönderimi, ölçümleme ve reklam hizmeti sağlayan iş ortaklarımızla yalnızca hizmetin gerektirdiği ölçüde paylaşılabilir. Yetkili kamu kurumlarına aktarım yalnızca hukuki talep üzerine yapılır. Reklam sağlayıcıları (ör. Google AdSense), kendi gizlilik politikalarına tabi olarak çerez ve benzeri teknolojiler kullanabilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Güvenlik"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Verilerin yetkisiz erişime, kayba, kötüye kullanıma karşı korunması için erişim kontrolü, şifreli iletişim (HTTPS), kayıt tutma ve düzenli gözden geçirme gibi teknik ve idari tedbirler uygulanır. Hiçbir sistemin mutlak güvenlik garantisi vermediğini belirtmek gerekir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Saklama"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Veriler, işleme amacı için gerekli olan süre ve mevzuatta öngörülen süreler boyunca saklanır. Süre sonunda silinir, yok edilir veya anonim hâle getirilir. Erişim kayıtları 5651 sayılı Kanun kapsamında tutulur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Çocukların Gizliliği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site, 18 yaş altındaki kullanıcılardan bilerek kişisel veri toplamayı amaçlamaz. Velayet sahibi bir ebeveyn veya vasi, çocuğuna ait verilerin silinmesini talep edebilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Haklarınız"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verilerinize erişme, düzeltme, silme, işlemeye itiraz ve zararın giderilmesini talep etme haklarınız bulunur. Talepleriniz için KVKK Aydınlatma Metni ve İlgili Kişi Başvuru Formu sayfalarımızı kullanabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Değişiklikler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Politika; hizmetlerdeki veya mevzuattaki değişikliklere göre güncellenebilir. Önemli değişiklikler sitede duyurulur. Güncel sürüm bu sayfada yayımlanır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "10. İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Gizlilikle ilgili soru ve talepleriniz için info@theblock.com.tr adresine yazabilirsiniz."}]}]}'::jsonb, 'yayinda', false, true, true)
