INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Kullanım Koşulları', 'kullanim-kosullari', 'theblock.com.tr kullanımına ilişkin hak ve yükümlülükler.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "theblock.com.tr''yi ziyaret ederek veya kullanarak bu koşulları kabul etmiş sayılırsınız. Koşullar zaman zaman güncellenebilir; güncel sürüm bu sayfada yayımlanır. Sitenin kullanımına devam etmeniz, güncel koşulları kabul ettiğiniz anlamına gelir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Tanımlar"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Site\": theblock.com.tr alan adı ve alt alan adları üzerinden sunulan tüm hizmetler."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"İçerik\": sitede yayımlanan haber, makale, fotoğraf, video, infografik ve diğer materyaller."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Kullanıcı\": siteyi ziyaret eden veya üyelik oluşturan gerçek kişi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "\"Hizmet\": site üzerinden sunulan okuma, arama, kaydetme, yorum, bülten ve benzeri işlevler."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Hizmetin Kapsamı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site, güncel haber ve bilgi sunmak amacıyla yayın yapar. İçerikler bilgilendirme amaçlıdır; yatırım, hukuk, sağlık veya vergi danışmanlığı niteliğinde değildir. Hizmetin kesintisiz veya hatasız olacağı garanti edilmez; bakım, güncelleme ve teknik arızalar nedeniyle erişim geçici olarak durabilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Fikri Mülkiyet"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitede yer alan içerikler telif hakkı ve ilgili mevzuatla korunur. Kaynak gösterilerek kısa alıntı yapılabilir. İçeriklerin izinsiz çoğaltılması, ticari amaçla yeniden yayımlanması, derlenmesi veya veri madenciliği yoluyla toplu olarak alınması yasaktır. Ayrıntılar için Telif Hakları sayfamızı inceleyin."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Kullanıcı Yükümlülükleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kullanıcı, siteyi hukuka uygun amaçlarla kullanmayı ve aşağıdaki davranışlardan kaçınmayı kabul eder:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yasa dışı, tehditkâr, hakaret içeren, nefret söylemi barındıran veya ayrımcılık yapan içerik paylaşmak."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Başkalarının telif, marka, gizlilik veya kişilik haklarını ihlal etmek."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yanıltıcı, spam niteliğinde veya reklam amaçlı yorum göndermek."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sitenin güvenliğini tehdit eden, otomatik araçlarla aşırı yük oluşturan veya erişimi engelleyen girişimlerde bulunmak."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Başka bir kullanıcının hesabını izinsiz kullanmak veya kimlik bilgilerini paylaşmak."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Kullanıcı İçeriği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yorum ve geri bildirimlerinizde paylaştığınız içerikten siz sorumlusunuz. Yorumlar yayın öncesi veya sonrasında moderasyona tabi tutulabilir; uygunsuz içerikler kaldırılabilir. Yorumlarınızın site üzerinde görüntülenmesi için siteye ücretsiz, dünya çapında ve süresiz bir kullanım izni vermiş olursunuz. Bu izin, içeriğin kaldırılmasından sonra arşiv kopyaları için makul ölçüde devam eder."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Reklam ve Sponsorlu İçerik"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site, reklam ve sponsorluk gelirleriyle varlığını sürdürür. Reklamlar editoryal içerikten açıkça ayrılır ve \"Reklam\" etiketiyle gösterilir. Sponsorlu veya iş birliği içeren içerikler ayrıca belirtilir. Reklam verenlerin editoryal içerik üzerinde etkisi yoktur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Üçüncü Taraf Bağlantılar"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site, üçüncü taraf sitelere bağlantılar içerebilir. Bu sitelerin içeriğinden, gizlilik uygulamalarından ve güvenliğinden ilgili site sahipleri sorumludur. Bağlantılar bir onay veya garanti anlamına gelmez."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Sorumluluğun Sınırlandırılması"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site yönetimi; içeriklerdeki hata, eksiklik veya güncellik sorunlarından, hizmet kesintilerinden veya kullanıcı içeriğinden doğabilecek dolaylı zararlardan, yürürlükteki mevzuatın izin verdiği ölçüde sorumlu tutulamaz. Bu hüküm, tüketici mevzuatından doğan zorunlu hakları ortadan kaldırmaz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Hesabın Askıya Alınması"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu koşullara aykırı davranış, güvenlik riski veya hukuki zorunluluk hâlinde kullanıcı hesabı geçici olarak askıya alınabilir veya kapatılabilir. Gerekli hâllerde yetkili makamlarla bilgi paylaşılabilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "10. Uygulanacak Hukuk"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu koşullardan doğan uyuşmazlıklarda Türkiye Cumhuriyeti mevzuatı uygulanır; yetkili mahkeme ve icra daireleri İstanbul''dur. Tüketici işlemlerinde tüketicinin yerleşim yerindeki tüketici hakem heyetleri ve mahkemeleri yetkilidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "11. İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Koşullarla ilgili sorularınız için info@theblock.com.tr adresine yazabilirsiniz."}]}]}'::jsonb, 'yayinda', false, true, true)
