INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Çerez Politikası ve Aydınlatma Metni', 'cerez-politikasi', 'Sitemizde kullanılan çerez türleri, amaçları ve tercihlerinizi yönetme yolları.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu metin, theblock.com.tr üzerinde kullanılan çerezler ve benzeri teknolojiler hakkında sizi bilgilendirmek amacıyla hazırlanmıştır. Çerezler, ziyaret ettiğiniz web siteleri tarafından tarayıcınıza kaydedilen küçük metin dosyalarıdır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Çerezlerin Kullanım Amaçları"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sitenin temel işlevlerini çalıştırmak (oturum, güvenlik, form doğrulama)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tercihlerinizi hatırlamak (tema, dil, yazı boyutu, sesli okuma ayarları)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ziyaret istatistiklerini ölçmek ve içerik performansını anlamak."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İlgi alanlarınıza uygun reklam göstermek ve reklam etkinliğini ölçmek."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Çerez Türleri"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Zorunlu çerezler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitenin çalışması için gereklidir. Oturum yönetimi, güvenlik doğrulaması ve tercihlerin korunması amacıyla kullanılır. Bu çerezler olmadan site düzgün çalışmayabilir."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "İşlevsel çerezler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Dil, tema, yazı boyutu, sesli okuma hızı gibi seçimlerinizi hatırlar. Bu çerezler devre dışı bırakıldığında tercihleriniz her ziyarette sıfırlanabilir."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Ölçümleme/analitik çerezleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sayfa görüntüleme sayısı, ziyaret süresi, yönlendiren kaynak gibi bilgileri toplar. Toplanan veriler kural olarak toplu ve anonimdir; sitenin hangi içeriklerinin ilgi çektiğini anlamamıza yardımcı olur."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Reklam çerezleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Google AdSense ve benzeri reklam sağlayıcıları tarafından yerleştirilebilir. İlgi alanına dayalı reklam gösterimi ve reklam ölçümü için kullanılır. Bu çerezler üçüncü taraf sağlayıcıların kendi politikalarına tabidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Saklama Süreleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Oturum çerezleri tarayıcıyı kapattığınızda silinir. Kalıcı çerezler ise türüne göre birkaç günden birkaç aya kadar saklanabilir. Süreler, çerezi yerleştiren tarafın ayarlarına göre değişebilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Çerezleri Yönetme"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tarayıcınızın ayarlarından çerezleri silebilir, engelleyebilir veya yalnızca belirli siteler için izin verebilirsiniz. Çerezleri tamamen engellemeniz hâlinde sitenin bazı bölümleri beklendiği gibi çalışmayabilir. Yaygın tarayıcılarda ayarlar \"Gizlilik\" veya \"Site verileri\" bölümünde yer alır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Üçüncü Taraf Hizmetler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitede Google Analytics ve Google AdSense gibi üçüncü taraf hizmetler kullanılabilir. Google''ın reklam çerezlerini yönetmek için adssettings.google.com adresini, ölçümleme tercihleri için tarayıcı eklentilerini kullanabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Kişisel Verilerle İlişkisi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Çerezler yoluyla elde edilen veriler, KVKK Aydınlatma Metni''nde açıklanan amaç ve hukuki sebeplerle işlenir. Çerez tercihleriniz, zorunlu çerezler dışında, tarayıcı ayarlarınız üzerinden yönetilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Güncellemeler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu politika; kullanılan çerezler veya mevzuat değiştiğinde güncellenebilir. Güncel sürüm bu sayfada yayımlanır. Sorularınız için info@theblock.com.tr adresine yazabilirsiniz."}]}]}'::jsonb, 'yayinda', false, true, true)
