INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Reklam ve Sponsorluk Politikası', 'reklam-politikasi', 'Reklam yerleşimi, sponsorlu içerik ve editoryal bağımsızlık ilkelerimiz.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "theblock.com.tr, yayın faaliyetlerini reklam gelirleri ve sponsorluklarla sürdürür. Bu politika; reklamların nasıl etiketlendiğini, hangi reklamların kabul edildiğini ve editoryal bağımsızlığın nasıl korunduğunu açıklar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Temel İlkeler"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklamlar editoryal içerikten görsel ve metinsel olarak açıkça ayrılır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sponsorlu veya iş birliği içeren içerikler \"Sponsorlu\", \"İş birliği\" veya benzeri etiketlerle belirtilir."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam verenlerin haber seçimi, başlık ve içerik üzerinde editoryal etkisi yoktur."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam yerleşimi okuyucu deneyimini ve içeriğe erişimi engellemeyecek biçimde planlanır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yanıltıcı, yasa dışı veya ayrımcılık içeren reklamlar kabul edilmez."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Reklam Türleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitede görüntülü reklam (banner), sponsorlu içerik, iş birliği içerikleri ve bülten sponsorlukları yer alabilir. Programatik reklamlar Google AdSense gibi üçüncü taraf ağlar üzerinden sunulur; bu ağların reklam politikaları ayrıca geçerlidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Etiketleme"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ticari içerikler, okuyucunun ayırt edebileceği biçimde etiketlenir. Etiketler gizlenmez, küçültülmez veya içerikle karışacak şekilde yerleştirilmez. Doğal görünümlü reklam (native) biçimlerinde de \"Reklam\" ibaresi bulunur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Editoryal Bağımsızlık"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber ve analizlerin hazırlanmasında reklam verenlerin talepleri dikkate alınmaz. Sponsorluk anlaşmaları yalnızca görünürlük ve yayın kapsamını belirler; içeriğin olumlu veya olumsuz sunulmasına ilişkin şart içeremez. Reklam ve haber ekipleri ayrı sorumluluk alanlarına sahiptir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Kabul Edilmeyen Reklamlar"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yasa dışı ürün veya hizmet tanıtımları."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yanıltıcı sağlık, finans veya hukuk iddiaları."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Nefret, şiddet veya ayrımcılık içeren mesajlar."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Telif veya marka hakkı ihlali içeren görseller."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Okuyucuyu yanıltan sahte arayüz veya \"haber gibi\" tasarımlar."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Marka Güvenliği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reklamların hassas içeriklerle (şiddet, felaket, yas) yan yana gelmemesine özen gösterilir. Ancak programatik reklam ağlarında yerleşim otomatik belirlendiği için nadir istisnalar olabilir; bildirim hâlinde gerekli düzeltme yapılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Reklam Başvurusu"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reklam, sponsorluk ve iş birliği talepleriniz için reklam@theblock.com.tr adresine yazabilirsiniz. Medya kiti, yerleşim seçenekleri ve fiyat bilgisi talep üzerine paylaşılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Şeffaflık ve Bildirim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Politikaya aykırı olduğunu düşündüğünüz bir reklamı info@theblock.com.tr adresine bildirebilirsiniz. Bildirimler incelenir ve gerekli görülen reklamlar kaldırılır."}]}]}'::jsonb, 'yayinda', false, true, true)
