INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Künye', 'kunye', 'theblock.com.tr hakkında kurumsal bilgiler, yayın ilkeleri ve iletişim.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "theblock.com.tr, güncel haber ve bilgiyi hızlı, doğrulanmış ve erişilebilir biçimde sunmayı amaçlayan bağımsız bir dijital haber platformudur. Ekonomi, siyaset, dünya, spor, teknoloji, yaşam ve kültür alanlarında içerik üretir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Yayın Anlayışımız"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Haberlerde doğruluk, tarafsızlık ve kaynak şeffaflığı esastır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hatalar tespit edildiğinde düzeltme yapılır ve düzeltme okuyucuya duyurulur."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam ve editoryal içerik birbirinden açıkça ayrılır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kişilik haklarına, mahremiyete ve masumiyet karinesine saygı gösterilir."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Erişilebilirlik ve okunabilirlik gözetilir; içerikler mobil öncelikli hazırlanır."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Yayın Kurulu ve Ekip"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "İçerikler; haber merkezi, editörler ve alanında uzman yazarlardan oluşan bir ekip tarafından hazırlanır. Yazar ve editör bilgileri, ilgili içeriklerin künyesinde ve yazar sayfalarında yer alır. İçeriklerin sorumluluğu yayın kurulundadır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Editoryal İlkeler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber üretim sürecimiz; kaynak doğrulama, çoklu kaynak kontrolü, başlık-içerik uyumu ve düzeltme süreçlerini kapsar. Ayrıntılı ilkeler için Editoryal İlkeler sayfamızı inceleyebilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Teknoloji ve Altyapı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site; hızlı erişim, güvenli iletişim ve ölçeklenebilirlik için modern bir altyapı üzerinde yayımlanır. Kişisel verilerin korunması ve çerez kullanımı konusunda KVKK Aydınlatma Metni ile Çerez Politikası geçerlidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Genel bilgi ve okuyucu geri bildirimleri: info@theblock.com.tr. Reklam ve sponsorluk: reklam@theblock.com.tr. Haber ihbarı ve düzeltme talepleri için İletişim sayfamızdaki kanalları kullanabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Yasal Bilgiler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site içerikleri telif hakkı ile korunur. Kullanım koşulları, gizlilik ve kişisel verilerin korunmasına ilişkin metinler sitede yayımlanır. Uyuşmazlıklarda Türkiye Cumhuriyeti mevzuatı uygulanır."}]}]}'::jsonb, 'yayinda', false, true, true)
