INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'İletişim', 'iletisim', 'Haber ihbarı, düzeltme talebi, reklam ve genel iletişim kanalları.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Okuyucularımızdan gelen geri bildirimler, yayın kalitemizi geliştirmemiz için önemlidir. Aşağıdaki kanallardan bize ulaşabilirsiniz. Talebinizin konusunu konu satırında belirtmeniz, daha hızlı yanıt almamızı sağlar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Genel İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: info@theblock.com.tr — Site, içerik ve genel sorular için."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Haber Merkezi ve İhbar"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: haber@theblock.com.tr — Haber ihbarı, bilgi ve belge paylaşımı için. İhbarınızı destekleyen belge, fotoğraf veya bağlantıları ekleyebilirsiniz. Kaynağınızın gizli kalmasını istiyorsanız bunu açıkça belirtin."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Düzeltme ve Yayın Etiği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: duzeltme@theblock.com.tr — Hatalı bilgi, başlık-içerik uyumsuzluğu veya yayın ilkelerine aykırılık bildirimleri için. Talebinizde içeriğin bağlantısını ve düzeltilmesi gereken noktayı belirtin. Düzeltmeler, doğrulama sonrası içerikte ve gerektiğinde ayrı bir notla duyurulur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Reklam ve İş Birlikleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: reklam@theblock.com.tr — Reklam, sponsorluk ve iş birliği talepleri için. Medya kiti ve yerleşim seçenekleri talep üzerine paylaşılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "KVKK ve Kişisel Veriler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: info@theblock.com.tr — Kişisel verilerinize ilişkin talepler için İlgili Kişi Başvuru Formu sayfamızdaki yöntemi kullanabilirsiniz. Başvurular en geç 30 gün içinde yanıtlanır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Teknik Destek"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "E-posta: destek@theblock.com.tr — Siteye erişim, üyelik, bülten ve teknik sorunlar için. Sorunu tanımlayan ekran görüntüsü ve kullandığınız tarayıcı bilgisi süreci hızlandırır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Çalışma Saatleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber merkezi 7/24 çalışır. Diğer talepler hafta içi 09.00–18.00 arasında yanıtlanır. Resmî tatillerde yanıt süresi uzayabilir."}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Acil güvenlik veya hayati risk içeren durumlarda lütfen önce 112 Acil Çağrı Merkezi''ni arayın. Sitemiz acil müdahale hizmeti sunmaz."}]}]}]}'::jsonb, 'yayinda', false, true, true)
