INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Telif Hakları ve İçerik Kullanımı', 'telif-haklari', 'İçeriklerimizin telif durumu, izinli kullanım koşulları ve ihlal bildirimi.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "theblock.com.tr üzerinde yayımlanan tüm haber, makale, fotoğraf, video, infografik, tasarım ve yazılım öğeleri 5846 sayılı Fikir ve Sanat Eserleri Kanunu kapsamında korunmaktadır. İçeriklerin hakları, aksi belirtilmedikçe site yönetimine veya ilgili hak sahibine aittir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. İzinli Kullanım"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kaynak ve bağlantı gösterilerek kısa alıntı yapılabilir."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Haber özetleri, sosyal medya paylaşımı ve kişisel kullanım serbesttir."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Eğitim ve araştırma amaçlı kullanımda kaynak açıkça belirtilmelidir."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. İzinsiz Kullanım"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "İçeriklerin bütün olarak veya büyük bölümünün kopyalanması, başka bir sitede yeniden yayımlanması, ticari kullanımı, derlenmesi ve otomatik araçlarla toplu olarak çekilmesi yasaktır. Bu tür kullanımlar için yazılı izin gerekir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Gömme (Embed)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sosyal medya kartları ve video oynatıcıları, sağladığımız gömme kodları aracılığıyla kullanılabilir. Gömme kodunun değiştirilmesi, çerçeve içinde reklam yerleştirilmesi veya içeriğin farklı biçimde sunulması kabul edilmez."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. RSS ve Otomatik Erişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "RSS akışları kişisel okuyucularda kullanılabilir. Akışların tam metin olarak başka sitelerde yayımlanması, yeniden dağıtılması veya ticari amaçla kullanılması izne tabidir. Aşırı istek oluşturan otomatik erişimler engellenebilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Üçüncü Taraf İçerikler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site, ajans ve iş ortaklarından sağlanan içerikler ile kamuya açık kaynaklardan alınmış görseller içerebilir. Bu içeriklerin hakları ilgili sahiplerine aittir ve kaynak belirtilir. Hak sahipliği konusunda bir hata olduğunu düşünüyorsanız bize bildirin."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. İhlal Bildirimi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Telif hakkınızın ihlal edildiğini düşünüyorsanız telif@theblock.com.tr adresine aşağıdaki bilgilerle başvurun: eserin tanımı, ihlal ettiğini düşündüğünüz bağlantı, hak sahibi olduğunuzu gösteren belge ve iletişim bilgileriniz. Bildirimler incelenir; haklı bulunması hâlinde içerik kaldırılır veya düzeltilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. İzin Talepleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ticari kullanım, yeniden yayımlama ve lisans talepleri için info@theblock.com.tr adresine yazabilirsiniz. Talebinizde kullanılacak içeriği, kullanım amacını ve yayın kanalını belirtin."}]}]}'::jsonb, 'yayinda', false, true, true)
