INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Editoryal İlkeler ve Yayın Politikası', 'editoryal-ilkeler', 'Haber üretiminde doğruluk, bağımsızlık, düzeltme ve şeffaflık ilkelerimiz.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu ilkeler, theblock.com.tr haber merkezinin içerik üretirken uyduğu standartları tanımlar. Amacımız; doğrulanmış, dengeli ve okuyucunun güvenebileceği içerik sunmaktır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Doğruluk ve Doğrulama"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yayımlanan her haber, en az iki bağımsız kaynak veya doğrulanabilir belge ile desteklenmeye çalışılır. Sosyal medya paylaşımları tek başına kaynak sayılmaz; görsel ve videoların doğruluğu kontrol edilir. Doğrulanamayan iddialar açıkça \"iddia\" olarak nitelendirilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Tarafsızlık ve Bağımsızlık"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Haber seçiminde ve sunumunda siyasi, ticari veya kişisel çıkar gözetilmez. Reklam verenler, sponsorlar ve hissedarlar editoryal kararlara müdahale edemez. Çıkar çatışması bulunan yazarlar bunu içerikte belirtir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Kaynak Kullanımı"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Kaynakların kimliği, güvenlikleri tehlikeye girmedikçe korunur."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Anonim kaynak yalnızca bilginin başka yolla doğrulanamadığı hâllerde kullanılır ve gerekçesi açıklanır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Basın bültenleri ve ajans içerikleri olduğu gibi yayımlanmaz; editoryal kontrol süzgecinden geçer."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Başlık ve İçerik Uyumu"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Başlık, spot ve görsel; içeriğin ana mesajını abartmadan yansıtır. Tıklama tuzağı (clickbait), yanıltıcı vaat ve merak boşluğu yaratan başlıklar kullanılmaz. Güncelleme gerektiren içeriklerde değişiklik tarihi belirtilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Düzeltme Politikası"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hata tespit edildiğinde içerik en kısa sürede düzeltilir. Önemli düzeltmelerde içeriğin altına açıklayıcı not eklenir. Okuyucular duzeltme@theblock.com.tr adresine hata bildirebilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Kişilik Hakları ve Mahremiyet"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Özel hayatın gizliliğine saygı esastır. Çocukların, suç mağdurlarının ve hassas grupların kimliği korunur. Yargı süreçlerinde masumiyet karinesi gözetilir; kesinleşmemiş hükümler kesinmiş gibi sunulmaz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Nefret Söylemi ve Ayrımcılık"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Nefret söylemi, ayrımcılık, şiddet çağrısı ve taciz içeren içerikler yayımlanmaz. Haber değeri taşıyan durumlarda bu ifadeler bağlam içinde ve gerekli uyarılarla aktarılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Yapay Zekâ Kullanımı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yapay zekâ araçları; özetleme, transkripsiyon, çeviri ve araştırma desteği gibi süreçlerde kullanılabilir. Yapay zekâ ile üretilen içerikler editoryal kontrol süzgecinden geçer ve okuyucuya açıkça belirtilir. Haberlerin nihai sorumluluğu insan editördedir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Reklam ve İçerik Ayrımı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reklam ve sponsorlu içerikler açıkça etiketlenir; haberlerle karıştırılmayacak biçimde sunulur. Ayrıntılar için Reklam ve Sponsorluk Politikası sayfasına bakabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "10. Şeffaflık ve Erişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Okuyucuların soru, öneri ve şikâyetlerini iletebilmesi için iletişim kanalları açıktır. İçeriklerde kullanılan kaynaklar, mümkün olduğunca bağlantı ile paylaşılır."}]}]}'::jsonb, 'yayinda', false, true, true)
