    title = EXCLUDED.title,
    spot = EXCLUDED.spot,
    detail = EXCLUDED.detail,
    kind = EXCLUDED.kind,
    status = 'yayinda',
    in_footer = true,
    updated_at = now();

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Bilgi Toplum Hizmetleri ve Yer Sağlayıcı Bilgileri', 'bilgi-toplum-hizmetleri', '5651 sayılı Kanun kapsamında yer sağlayıcı bilgileri ve içerik kaldırma başvuruları.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu sayfa, 5651 sayılı İnternet Ortamında Yapılan Yayınların Düzenlenmesi ve Bu Yayınlar Yoluyla İşlenen Suçlarla Mücadele Edilmesi Hakkında Kanun kapsamında bilgilendirme amacıyla hazırlanmıştır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Yer Sağlayıcı"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitemiz, yer sağlayıcı sıfatıyla yayın hizmeti sunmaktadır. Yer sağlayıcı, kullanıcılar tarafından sağlanan içerikleri kontrol etmekle yükümlü değildir; ancak hukuka aykırı içeriğin bildirilmesi hâlinde gerekli işlemleri yapar."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. İçerik Sorumluluğu"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitede yayımlanan haber ve içeriklerin sorumluluğu yayın kuruluna aittir. Kullanıcı yorumları, yorumu yazan kullanıcının sorumluluğundadır. Yorumlar moderasyona tabi tutulabilir ve uygunsuz içerikler kaldırılabilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Hukuka Aykırı İçerik Bildirimi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Hukuka aykırı olduğunu düşündüğünüz içerikleri info@theblock.com.tr adresine, içeriğin bağlantısı ve gerekçesiyle bildirebilirsiniz. Bildirimlerde kimlik ve iletişim bilgilerinizin yer alması gerekir. Talepler mevzuattaki usule göre değerlendirilir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Erişim Engelleme Kararları"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yetkili mahkeme veya kurumların erişim engelleme kararları, kararın kapsamına göre uygulanır. Uygulanan kararlara ilişkin bilgilendirme, mevzuatın izin verdiği ölçüde yapılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Trafik Bilgileri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Erişim kayıtları, 5651 sayılı Kanun ve ilgili yönetmelikte öngörülen süreler boyunca saklanır; yalnızca yetkili kurumların hukuka uygun talepleri doğrultusunda paylaşılır. Kişisel verilerin işlenmesine ilişkin ayrıntılar KVKK Aydınlatma Metni''nde yer alır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Yer sağlayıcı ve içerik bildirimleri için: info@theblock.com.tr. Telif ihlali bildirimleri için Telif Hakları sayfasındaki yöntemi kullanabilirsiniz."}]}]}'::jsonb, 'yayinda', false, true, true)
