-- Footer ayarındaki Kurumsal sütununu ve üst şeridi güncelle.
UPDATE settings SET value = jsonb_set(value, '{cols}', (
    SELECT jsonb_agg(
        CASE WHEN c->>'title' = 'Kurumsal'
             THEN jsonb_set(c, '{links}', '[{"label": "Çerez Politikası", "url": "/cerez-politikasi"}, {"label": "Kullanım Koşulları", "url": "/kullanim-kosullari"}, {"label": "Gizlilik Politikası", "url": "/gizlilik-politikasi"}, {"label": "KVKK Aydınlatma", "url": "/kvkk"}, {"label": "İlgili Kişi Başvuru Formu", "url": "/kvkk-basvuru"}, {"label": "Telif Hakları", "url": "/telif-haklari"}, {"label": "Editoryal İlkeler", "url": "/editoryal-ilkeler"}, {"label": "Bilgi Toplum Hizmetleri", "url": "/bilgi-toplum-hizmetleri"}, {"label": "Künyemiz", "url": "/kunye"}, {"label": "Bize Ulaşın", "url": "/iletisim"}]'::jsonb)
             ELSE c END ORDER BY ord)
    FROM jsonb_array_elements(value->'cols') WITH ORDINALITY AS t(c, ord)
)) WHERE section = 'footer' AND key = 'ana' AND value ? 'cols';

UPDATE settings SET value = jsonb_set(value, '{strip}', '[{"label": "Künyemiz", "url": "/kunye"}, {"label": "İletişim", "url": "/iletisim"}, {"label": "Kullanım Koşulları", "url": "/kullanim-kosullari"}, {"label": "KVKK", "url": "/kvkk"}, {"label": "Gizlilik Politikası", "url": "/gizlilik-politikasi"}]'::jsonb)
WHERE section = 'footer' AND key = 'ana' AND value ? 'strip';

-- Eski adresler: kalıcı yönlendirme (301). redirects tablosu site bazlıdır
-- (PK: site_id + source_path); her site için aynı yönlendirme yazılır.
INSERT INTO redirects (site_id, source_path, target_url, status_code)
SELECT s.id, r.src, r.dst, 301
FROM sites s
CROSS JOIN (VALUES
    ('/bize-ulasin', '/iletisim'),
    ('/sayfa/bize-ulasin', '/iletisim'),
    ('/kvkk-aydinlatma', '/kvkk'),
    ('/sayfa/kvkk-aydinlatma', '/kvkk'),
    ('/iletisim-formu', '/iletisim')
) AS r(src, dst)
ON CONFLICT (site_id, source_path) DO UPDATE SET target_url = EXCLUDED.target_url, status_code = 301;

